async function saveFile(name, data) {
  let dl = null; try { if (window.claude && typeof window.claude.use === 'function') dl = await window.claude.use('downloads'); } catch (e) { dl = null; }
  if (dl) { try { await dl.save({ filename: name, data }); toast('Saved ' + name); return true; } catch (err) { if (err && err.code === 'declined') toast('Save cancelled'); else toast('Could not save the file here (' + ((err && err.code) || 'error') + ')', 'warn'); return false; } }
  const blob = data instanceof Blob ? data : new Blob([data]); const a = h('a', { href: URL.createObjectURL(blob), download: name }); document.body.append(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1500); toast('Downloading ' + name); return true;
}
