  hemi.intensity = S.ambient; sun.intensity = S.sun; hemi.color.set(S.skyLight || '#dfe8f0'); hemi.groundColor.set(S.groundLight || '#3a3530'); sun.color.set(S.sunColor || '#fff4e0');
  ENG.mirrorRes = (ENG.QUALITY[S.quality] || ENG.QUALITY.high).mirror; vpost.apply(S, true); const el = S.sunAngle * D2R, az = S.sunYaw * D2R; sun.position.set(Math.cos(el) * Math.sin(az), Math.sin(el), Math.cos(el) * Math.cos(az)).multiplyScalar(80); renderer.shadowMap.enabled = !!S.shadows; sun.castShadow = !!S.shadows;
