/* ---------------- keyboard ---------------- */
function isTyping(t) { const tag = (t.tagName || '').toLowerCase(); return (tag === 'input' && !['checkbox', 'range', 'color', 'button', 'radio'].includes(t.type)) || tag === 'textarea' || tag === 'select' || t.isContentEditable; }
window.addEventListener('keydown', e => {
  if (Ed.playing) return;
  const ctrl = e.ctrlKey || e.metaKey;
  if (ctrl && e.code === 'KeyS') { e.preventDefault(); saveLocal(); return; }
  if (e.altKey && e.code === 'KeyP') { e.preventDefault(); play(false); return; }
  if (Ed.modalOpen) { if (e.code === 'Escape') closeModal(); return; }
  if (Ed.menuEl) return;
  if (isTyping(e.target)) { if (e.code === 'Escape') e.target.blur(); return; }
  if (Ed.tab === 'model') { modelKey(e, ctrl); return; }
  if (Ed.tab === 'level' && !ctrl && e.code === 'KeyL' && !Ed.playing) { e.preventDefault(); openLibrary(); return; }
  if (Ed.tab === 'paint') { paintKey(e, ctrl); return; }
  if (Ed.tab === 'logic') { if (ctrl && e.code === 'KeyZ') { e.preventDefault(); e.shiftKey ? redo() : undo(); } else if (ctrl && e.code === 'KeyY') { e.preventDefault(); redo(); } return; }
  if (Ed.tab !== 'level' && Ed.tab !== 'cutscene') return;
  V.keys[e.code] = true;
  if (V.rmb) { if (['KeyW', 'KeyA', 'KeyS', 'KeyD', 'KeyQ', 'KeyE'].includes(e.code)) e.preventDefault(); return; }
  if (ctrl) { if (e.code === 'KeyZ') { e.preventDefault(); e.shiftKey ? redo() : undo(); } else if (e.code === 'KeyY') { e.preventDefault(); redo(); } else if (e.code === 'KeyD') { e.preventDefault(); duplicate(); } else if (e.code === 'KeyH') { e.preventDefault(); unhideAll(); } return; }
  if (Ed.tab === 'cutscene') { if (e.code === 'Escape' && Ed.preview) stopPreview(); if (e.code === 'KeyK') addCsKey(); return; }
  switch (e.code) {
    case 'KeyW': setMode('translate'); break; case 'KeyE': setMode('rotate'); break;
    case 'KeyR': if (Ed.placing) { Ed.placing.rot = (Ed.placing.rot + 90) % 360; if (Ed.ghost) Ed.ghost.rotation.y = Ed.placing.rot * D2R; } else setMode('scale'); break;
    case 'Space': e.preventDefault(); cycleMode(); break; case 'Backquote': toggleSpace(); break;
    case 'KeyF': focusSel(); break; case 'End': dropSel(); break;
    case 'Delete': case 'Backspace': e.preventDefault(); deleteSel(); break;
    case 'KeyG': toggleGameView(); break; case 'KeyH': hideSel(); break;
    case 'BracketLeft': gridStep(-1); break; case 'BracketRight': gridStep(1); break;
    case 'Escape': if (Ed.placing) cancelPlacing(); else select(null); break;
  }
});
window.addEventListener('keyup', e => { V.keys[e.code] = false; });
window.addEventListener('blur', () => { V.keys = {}; V.rmb = V.mmb = V.orbit = false; edUnlock(); });

