    Object.values(Ed.project.assets.models).forEach(a => T.append(tile(modelThumb(a), a.name, 'Place ' + a.name, Ed.placing && Ed.placing.preset && Ed.placing.preset.props && Ed.placing.preset.props.asset === a.id, () => startPlacing('model', { props: { asset: a.id }, name: a.name.replace(/\.[^.]+$/, '') }), ico('box', 26))));
