  Object.entries(A.models).forEach(([id, a]) => body.append(row('model', id, a))); Object.entries(A.images).forEach(([id, a]) => body.append(row('texture', id, a))); Object.entries(A.audio).forEach(([id, a]) => body.append(row('audio', id, a)));
