async function importAssets() {
  const files = await pickFile('.glb,.gltf,.obj,.png,.jpg,.jpeg,.webp,.wav,.mp3,.ogg', true); if (!files.length) return;
  let lastModel = null;
  for (const f of files) {
    const ext = f.name.split('.').pop().toLowerCase(), id = ENG.uid();
    try {
      if (ext === 'obj') { Ed.project.assets.models[id] = { id, name: f.name, kind: 'obj', data: await readAs(f, 'readAsText') }; lastModel = id; }
      else if (ext === 'glb' || ext === 'gltf') { Ed.project.assets.models[id] = { id, name: f.name, kind: 'gltf', data: await readAs(f, 'readAsDataURL') }; lastModel = id; }
      else if (['png', 'jpg', 'jpeg', 'webp'].includes(ext)) { Ed.project.assets.images[id] = { id, name: f.name, data: await readAs(f, 'readAsDataURL') }; toast(f.name + ' added. Pick it in any Texture menu.'); }
      else if (['wav', 'mp3', 'ogg'].includes(ext)) { Ed.project.assets.audio[id] = { id, name: f.name, data: await readAs(f, 'readAsDataURL'), bus: 'sfx' }; toast(f.name + ' added. Pick it in any Sound menu.'); }
    } catch (e) { toast('Could not read ' + f.name, 'warn'); }
  }
  markDirty();
  if (lastModel) { const a = Ed.project.assets.models[lastModel]; toast('Loading ' + a.name + '…'); const m = await ENG.loadModel(a); if (!m) { toast(a.name + ' could not be loaded. For .gltf files with separate .bin files, export as .glb instead.', 'warn'); delete Ed.project.assets.models[lastModel]; return; } Ed.cat = 'Imported'; renderLibrary(); startPlacing('model', { props: { asset: a.id }, name: a.name.replace(/\.[^.]+$/, '') }); toast(a.name + ' ready. Click in the level to place it.'); }
  else if (Ed.tab === 'sound') renderSound();
}

