function dungeonProject() { const p = emptyProject(); p.name = 'Dungeon run'; p.objects = []; p.settings.proc.seed = Math.floor(Math.random() * 99999) + 1; p.settings.proc.regen = true; p.settings.sky = p.settings.fogColor = '#20262c'; p.settings.fog = .03; p.settings.sun = .3; p.settings.ambient = .45; p.objects = ENG.generateDungeon(p.settings.proc); return p; }
