  const rows = lr.hist.filter(x => LS.hist === 'all' || (LS.hist === 'err' ? x.k === 'error' : ['do', 'var', 'event'].includes(x.k)));
  const box = h('div', { class: 'scroll hist' });
  rows.forEach(x => box.append(h('div', { class: 'hrow k-' + x.k, tabindex: 0, role: 'button', onclick: () => { if (!x.b) return; const own = LGX.allBehaviors(Ed.project).find(e => e.b.id === x.b); if (!own) { toast('That behavior no longer exists'); return; } LS.filter = own.owner ? own.owner.id : 'level'; renderCards(); renderLogicLeft(); flashCard(x.b, x.path); }, onkeydown: e => { if (e.key === 'Enter') e.currentTarget.click(); } }, h('span', { class: 'ht' }, x.t.toFixed(1) + 's'), h('span', { class: 'hk' }, HK[x.k] || x.k), h('span', null, x.name ? h('b', null, x.name + ': ') : null, x.m))));
  if (!rows.length) box.append(h('p', { class: 'help' }, 'Nothing to show for this filter.'));
  R.append(box);
  const vs = Ed.project.logic.vars; if (vs.length) { const t = h('div', { class: 'vend' }, h('div', { class: 'sub', style: 'padding:8px 0 4px' }, 'Variables at the end of the run')); vs.forEach(v => t.append(h('div', { class: 'vline' }, h('span', null, v.name), h('span', { class: 'dim' }, LGX.fmtVal(v.type, LGX.coerce(v.type, v.init))), h('span', null, '→'), h('b', null, lr.vars[v.id] === undefined ? 'n/a' : LGX.fmtVal(v.type, lr.vars[v.id]))))); R.append(t); }
