  p.hud.push({ id: ENG.uid(), kind: 'credits', x: 92, y: 8, scale: 1, color: '#ffd84a', opacity: 1, font: 'Chakra Petch', label: 'CREDITS' }, { id: ENG.uid(), kind: 'floor', x: 92, y: 18, scale: .9, color: '#7ff0e4', opacity: 1, font: 'Chakra Petch', label: 'FLOOR' },
    { id: ENG.uid(), kind: 'bossbar', x: 50, y: 13, scale: 1, color: '#ff4fb8', opacity: 1, font: 'Chakra Petch', width: 520 }, { id: ENG.uid(), kind: 'perks', x: 14, y: 70, scale: .85, color: '#c9a8ff', opacity: 1, font: 'Barlow', label: 'UPGRADES' },
    { id: ENG.uid(), kind: 'text', x: 8, y: 15, scale: .7, color: '#c3ccd4', opacity: .9, font: 'Chakra Petch', text: 'Kills {kills}' });
  /* Logic Tiles */
