const LIB_ORDER = ['Players', 'Building', 'Building kit', 'Gameplay', 'Weapons', 'Characters', 'Props', 'Lights and FX', 'My models', 'Imported'];
const INTERACTIVE = new Set(['switch', 'door', 'interact', 'pickup', 'trigger', 'checkpoint', 'mover', 'trap', 'spawner', 'player_start']), PHYS = new Set(['crate', 'barrel', 'glass', 'mirror', 'mover', 'trap']), LIGHTS = new Set(['light', 'spotlight', 'shaft', 'emitter', 'sign', 'mirror']);
