const HG_PROMPT = 'Please make this game Vira-ready so I can open it in Vira Engine (File > Import HTML game) and edit it there. Keep the gameplay exactly the same.\n' + VI.READY.map(x => '- ' + x).join('\n');

/* edits and undo */
