/* play, export, import */
function hgPlay(newTab) {
  let html; try { html = hgBuild(); } catch (e) { console.error(e); toast('The game could not be put together: ' + e.message, 'warn'); return; }
  const url = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
  if (newTab) { const w = window.open(url, '_blank'); if (!w) toast('The browser blocked the new tab. Allow pop-ups for Vira and try again.', 'warn'); setTimeout(() => URL.revokeObjectURL(url), 30 * 60 * 1000); return; }
  if (Ed.playing) return; closeMenu(); const L = $('#playLayer'); L.innerHTML = ''; L.style.display = 'block'; Ed.playing = true; HG.url = url;
  const fr = h('iframe', { src: url, title: Ed.project.name, allow: 'xr-spatial-tracking; fullscreen; autoplay; gamepad; pointer-lock', allowfullscreen: true, style: 'position:absolute;inset:0;width:100%;height:100%;border:0;background:#000' });
  L.append(fr, h('button', { class: 'btn sm hgback', onclick: hgStop }, 'Back to editor')); setTimeout(() => fr.focus(), 60);
}
function hgStop() { if (HG.url) { URL.revokeObjectURL(HG.url); HG.url = null; } stopPlay(null); if (Ed.tab === 'game') hgRender(); }
