  modal(p.name + ' is in Vira', h('div', null, h('p', null, `Found ${A.tables.length} data table${A.tables.length === 1 ? '' : 's'} and ${A.consts.length} setting${A.consts.length === 1 ? '' : 's'} you can change without touching code. Pick one on the left, change a value, then press Play.`),
    A.tables.length + A.consts.length === 0 ? h('p', null, 'This game keeps its numbers inside its code, so there were no tables to show. You can still edit the code, or ask Claude to make the game Vira-ready (see the Overview).') : null,
    ext ? h('p', null, `${ext} file${ext > 1 ? 's' : ''} still load${ext > 1 ? '' : 's'} from the internet. The Overview lists ${ext > 1 ? 'them' : 'it'}.`) : null), [['Start editing', null, 'primary']]);
