async function openProjectFile() {
  const [f] = await pickFile('.json,application/json'); if (!f) return; let p; try { p = JSON.parse(await readAs(f, 'readAsText')); } catch (e) { toast('That file could not be read. It may be damaged or not a project file.', 'warn'); return; }
  if (p && p.vira === 'backup' && Ed.safety) { Ed.safety.restoreBackup(p); return; }
  /* anything shaped like a project opens; the repair pass in project.js fixes what is missing or broken */
  if (!p || typeof p !== 'object' || Array.isArray(p) || !(Array.isArray(p.objects) || p.settings || p.v)) { toast('That file is not a Vira project', 'warn'); return; }
  if (Ed.dirty) saveLocal(true); if (await loadProject(p, null)) toast('Opened ' + Ed.project.name);
}
